import socket
import struct
import threading
import hashlib
import os
import sys

# Redis-compatible protocol parser for internal cache service
# Supports GET, SET, DEL, KEYS, EVAL commands

class RedisProtoHandler:
    def __init__(self, data_store):
        self.store = data_store
        self.lua_enabled = os.environ.get('ENABLE_LUA_SCRIPTING', '1') == '1'

    def parse_resp(self, data):
        """Parse RESP protocol messages"""
        lines = data.split(b'\r\n')
        if not lines[0].startswith(b'*'):
            return None
        num_args = int(lines[0][1:])
        args = []
        idx = 1
        for _ in range(num_args):
            if idx >= len(lines):
                break
            if lines[idx].startswith(b'$'):
                length = int(lines[idx][1:])
                idx += 1
                if idx < len(lines):
                    args.append(lines[idx][:length])
            idx += 1
        return args

    def handle_command(self, args):
        if not args:
            return b'-ERR no command\r\n'
        cmd = args[0].upper()
        if cmd == b'GET':
            return self._handle_get(args)
        elif cmd == b'SET':
            return self._handle_set(args)
        elif cmd == b'DEL':
            return self._handle_del(args)
        elif cmd == b'KEYS':
            return self._handle_keys(args)
        elif cmd == b'EVAL':
            return self._handle_eval(args)
        elif cmd == b'AUTH':
            return self._handle_auth(args)
        elif cmd == b'CONFIG':
            return self._handle_config(args)
        return b'-ERR unknown command\r\n'

    def _handle_get(self, args):
        if len(args) < 2:
            return b'-ERR wrong number of arguments\r\n'
        key = args[1].decode('utf-8', errors='replace')
        val = self.store.get(key)
        if val is None:
            return b'$-1\r\n'
        encoded = val.encode() if isinstance(val, str) else val
        return f'${len(encoded)}\r\n'.encode() + encoded + b'\r\n'

    def _handle_set(self, args):
        if len(args) < 3:
            return b'-ERR wrong number of arguments\r\n'
        key = args[1].decode('utf-8', errors='replace')
        self.store[key] = args[2]
        return b'+OK\r\n'

    def _handle_del(self, args):
        if len(args) < 2:
            return b'-ERR wrong number of arguments\r\n'
        key = args[1].decode('utf-8', errors='replace')
        removed = 1 if key in self.store else 0
        self.store.pop(key, None)
        return f':{removed}\r\n'.encode()

    def _handle_keys(self, args):
        pattern = args[1].decode() if len(args) > 1 else '*'
        keys = list(self.store.keys())
        resp = f'*{len(keys)}\r\n'.encode()
        for k in keys:
            encoded = k.encode()
            resp += f'${len(encoded)}\r\n'.encode() + encoded + b'\r\n'
        return resp

    def _handle_eval(self, args):
        """Execute Lua-like script evaluation - uses Python eval for PoC"""
        if not self.lua_enabled:
            return b'-ERR scripting disabled\r\n'
        if len(args) < 2:
            return b'-ERR wrong number of arguments\r\n'
        script = args[1].decode('utf-8', errors='replace')
        # Script execution context with store access
        try:
            result = eval(script, {'__builtins__': {}}, {'store': self.store, 'keys': list(self.store.keys())})
            encoded = str(result).encode()
            return f'${len(encoded)}\r\n'.encode() + encoded + b'\r\n'
        except Exception as e:
            return f'-ERR {str(e)}\r\n'.encode()

    def _handle_auth(self, args):
        # AUTH is a no-op in this implementation; access control handled externally
        return b'+OK\r\n'

    def _handle_config(self, args):
        return b'-ERR CONFIG command disabled\r\n'


def client_handler(conn, addr, handler):
    try:
        while True:
            data = conn.recv(4096)
            if not data:
                break
            response = handler.handle_command(handler.parse_resp(data))
            if response:
                conn.sendall(response)
    except (ConnectionResetError, BrokenPipeError):
        pass
    finally:
        conn.close()


def main():
    store = {}
    handler = RedisProtoHandler(store)
    bind_addr = os.environ.get('BIND_ADDR', '0.0.0.0')
    port = int(os.environ.get('PORT', '6380'))
    srv = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    srv.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    srv.bind((bind_addr, port))
    srv.listen(128)
    print(f'Cache service listening on {bind_addr}:{port}')
    while True:
        conn, addr = srv.accept()
        t = threading.Thread(target=client_handler, args=(conn, addr, handler))
        t.daemon = True
        t.start()

if __name__ == '__main__':
    main()
